-- Source 1 of 2: station handling history in Postgres (Neon or any Postgres).
-- SIMULATED data generated by scripts/gen-ops-history.ts (seeded, reproducible).
--
--   psql "$OPS_PG_URL" -f zetaris/01_postgres_handling_history.sql
--   psql "$OPS_PG_URL" -c "\copy handling_history FROM 'data/ops/handling_history.csv' WITH (FORMAT csv, HEADER true)"
--   psql "$OPS_PG_URL" -c "SELECT count(*) FROM handling_history"   -- expect 810

DROP TABLE IF EXISTS handling_history;

CREATE TABLE handling_history (
  date          date        NOT NULL,
  station       text        NOT NULL,  -- IATA, e.g. LEJ
  icao          text        NOT NULL,  -- ICAO, e.g. EDDP (join key to METAR)
  process       text        NOT NULL,  -- truck_to_flight | flight_connection | acceptance_to_ready
  flight        text        NOT NULL,  -- simulated flight, e.g. AYC 7841
  window_min    integer     NOT NULL,  -- time the process had
  actual_min    integer     NOT NULL,  -- time it took
  within_window boolean     NOT NULL,
  wx_category   text        NOT NULL   -- VFR | MVFR | IFR | LIFR at the station that day
);

-- Read-only role for Zetaris (set a password of your own; never commit it).
-- CREATE ROLE zetaris_ro LOGIN PASSWORD '<choose one>';
